from src.matrix_ops import transpose, rotate_90, spiral_order


def test_transpose():
    m = [[1, 2, 3], [4, 5, 6]]
    assert transpose(m) == [[1, 4], [2, 5], [3, 6]]


def test_rotate_90():
    m = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert rotate_90(m) == [[7, 4, 1], [8, 5, 2], [9, 6, 3]]


def test_spiral_order_3x3():
    m = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert spiral_order(m) == [1, 2, 3, 6, 9, 8, 7, 4, 5]


def test_spiral_order_1x4():
    m = [[1, 2, 3, 4]]
    assert spiral_order(m) == [1, 2, 3, 4]


def test_transpose_square():
    m = [[1, 2], [3, 4]]
    assert transpose(m) == [[1, 3], [2, 4]]
